//! 🕸️ CLI: `bun ./📜️script.ts os run <bundle>.studio [--node <id>] [--watch] [--dry]` shells out to
//! `cargo run -p semio-framework-os-run --release -- <same args>`. This binary owns argv parsing and
//! studio-bundle plumbing only — all the actual dirty/clean and execution logic lives in the library.

use semio_framework_os_run::{plan, register_builtin_converters, SpaceBundle, SpaceRunner, WasmtimeNodeHost};
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use store::BlobStore;

//#region 🔖️PluginArtifacts
// 🤖️ Generated by the plugin registry's `generate` nx target (`bun nx run @semio-tech/plugin-
// registry:generate`) — `pub const PLUGIN_WASM_ARTIFACTS: &[(&str, &str)]`, each entry a plugin id
// paired with its compiled component `.wasm`'s path relative to the repo root, under cargo's own
// `target/wasm32-wasip2/wasm-release/` (see `resolve_plugin_paths` below). Gitignored build output
// regenerated by that nx target; this `include!` path is computed from `CARGO_MANIFEST_DIR` (this
// crate's own directory), not guessed.
include!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../🔌️plugin/⚡️implementations/🟦️typescript/📇️registry/🤖️generated/🦀️artifacts.rs"));

/// 🧭️ Locates the repo root: `SEMIO_REPO_ROOT` (already plumbed by `📜️script.ts`'s `os run` region)
/// when present and valid, else walks up from this crate's own compiled-in `CARGO_MANIFEST_DIR`
/// looking for `nx.json` — so a direct `cargo run -p semio-framework-os-run` (bypassing the script,
/// from an arbitrary working directory) still resolves correctly.
fn find_repo_root() -> Result<PathBuf, String> {
    if let Ok(value) = std::env::var("SEMIO_REPO_ROOT") {
        let candidate = PathBuf::from(value);
        if candidate.join("nx.json").is_file() {
            return Ok(candidate);
        }
    }
    let mut candidate = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    loop {
        if candidate.join("nx.json").is_file() {
            return Ok(candidate);
        }
        if !candidate.pop() {
            return Err("could not locate the repo root (no nx.json found above SEMIO_REPO_ROOT or CARGO_MANIFEST_DIR)".to_string());
        }
    }
}

/// 🗺️ Resolves every plugin id this run actually needs to its compiled `.wasm` path under cargo's own
/// `target/wasm32-wasip2/wasm-release/` build output (repo-root relative — see `emitRustArtifacts` in
/// the plugin registry script for why this is no longer the dev build's `plugin-modules/` copy). Fails
/// loudly and by name — rather than the obscure wasmtime "file not found" a missing artifact used to
/// produce — when a plugin isn't registered at all (registry stale: `bun nx run @semio-tech/plugin-
/// registry:generate`) or is registered but not yet built (`bun nx run @semio-tech/framework-os-dev:
/// build -- <plugin id>`, the same command `📜️script.ts`'s own `os run` preflight already names). That
/// TypeScript preflight runs first for the common case; this is this binary's own defense in depth for
/// a direct `cargo run` invocation that bypasses it.
fn resolve_plugin_paths(repo_root: &Path, plugin_ids: impl Iterator<Item = String>) -> Result<HashMap<String, PathBuf>, String> {
    let artifact_by_plugin: HashMap<&str, &str> = PLUGIN_WASM_ARTIFACTS.iter().map(|(plugin_id, relative_path)| (*plugin_id, *relative_path)).collect();
    let mut resolved = HashMap::new();
    for plugin_id in plugin_ids.collect::<BTreeSet<_>>() {
        let relative_path = artifact_by_plugin.get(plugin_id.as_str()).ok_or_else(|| format!("plugin `{plugin_id}` is not in the plugin registry — regenerate it: `bun nx run @semio-tech/plugin-registry:generate`"))?;
        let path = repo_root.join(relative_path);
        if !path.is_file() {
            return Err(format!("plugin `{plugin_id}`'s compiled wasm is missing at {}; build it: `bun nx run @semio-tech/framework-os-dev:build -- {plugin_id}`", path.display()));
        }
        resolved.insert(plugin_id, path);
    }
    Ok(resolved)
}
//#endregion 🔖️PluginArtifacts

struct Args {
    bundle: PathBuf,
    dry: bool,
    watch: bool,
    only_node: Option<String>,
}

fn parse_args() -> Result<Args, String> {
    let mut bundle: Option<PathBuf> = None;
    let mut dry = false;
    let mut watch = false;
    let mut only_node: Option<String> = None;
    let mut argv = std::env::args().skip(1);
    while let Some(arg) = argv.next() {
        match arg.as_str() {
            "--dry" => dry = true,
            "--watch" => watch = true,
            "--node" => only_node = Some(argv.next().ok_or("--node requires a value")?),
            other if !other.starts_with("--") => bundle = Some(PathBuf::from(other)),
            other => return Err(format!("unknown flag {other}")),
        }
    }
    let bundle = bundle.ok_or_else(|| "usage: os run <bundle>.studio [--node <id>] [--watch] [--dry]".to_string())?;
    Ok(Args { bundle, dry, watch, only_node })
}

fn main() {
    let args = match parse_args() {
        Ok(args) => args,
        Err(message) => {
            eprintln!("[os run] {message}");
            std::process::exit(1);
        }
    };
    if args.watch {
        eprintln!("[os run] --watch is not implemented yet — re-run the command instead for now (see HEADLESS-MEDIA-CONTRACT follow-up)");
        std::process::exit(1);
    }
    if let Err(error) = run(&args) {
        eprintln!("[os run] {error}");
        std::process::exit(1);
    }
}

fn run(args: &Args) -> Result<(), Box<dyn std::error::Error>> {
    // 🔌️ One-time registration of every framework-builtin `MediaConvertFn` this crate ships a real
    // body for (Vector→Raster today) — mirrors `register_artifact_descriptors`'s "call at
    // composition-root startup, beside plugin resolution" placement (`os-core`'s `PluginHost::
    // load_plugin` can't call this itself: it would be a reverse dependency on this crate).
    register_builtin_converters();
    let bundle = SpaceBundle::open(&args.bundle);
    let (space_pack, space_spr) = bundle.read_space_document()?;
    // 🧬️ `OsProjection`/`OsOperation` are dissolved (os-core dissolve, `## The inversion`) — the
    // studio bundle's `space.os.pack`/`.spr` files now carry a `workflow::WorkflowDocument`/
    // `WorkflowOperation` pair (the `s.workflow` artifact document) instead. `SpaceBundle`'s own
    // `space_document_pack_path`/`space_document_spr_path` filenames are unchanged here (a bundle
    // on-disk layout migration is out of scope for this wave) — only the typed decode target moved.
    let parsed: store::ParsedDocumentText<semio_framework_os::WorkflowDocument, semio_framework_os::WorkflowOperation> = store::parse_document_pack(&space_pack, &space_spr).map_err(|error| error.to_string())?;
    let projection = parsed.projection;

    let mut graph = projection.graph.clone();
    if let Some(node_id) = &args.only_node {
        graph.nodes.retain(|node| &node.id == node_id);
        graph.edges.retain(|edge| &edge.source_node_id == node_id || &edge.target_node_id == node_id);
    }

    let mut documents: BTreeMap<String, (Vec<u8>, Vec<u8>)> = BTreeMap::new();
    let mut configs: BTreeMap<String, (Vec<u8>, Vec<u8>)> = BTreeMap::new();
    for node in &graph.nodes {
        documents.insert(node.document_ref.clone(), bundle.read_document(&node.document_ref)?);
        configs.insert(node.config_ref.clone(), bundle.read_config(&node.config_ref)?);
    }

    let mut state = bundle.load_run_state()?;

    if args.dry {
        let report = plan(&graph, &documents, &configs, &state)?;
        println!("recompute: {:?}", report.recomputed);
        println!("clean:     {:?}", report.clean);
        return Ok(());
    }

    let relevant_plugin_ids: BTreeSet<String> = graph.nodes.iter().map(|node| node.plugin_id.clone()).collect();

    let repo_root = find_repo_root()?;
    let plugin_paths = resolve_plugin_paths(&repo_root, relevant_plugin_ids.into_iter())?;
    let blob_store: Arc<dyn BlobStore> = Arc::new(bundle.blob_store());
    let host = WasmtimeNodeHost::new(plugin_paths, Arc::clone(&blob_store));
    let mut runner = SpaceRunner::new(host, blob_store);
    let mut cache = bundle.media_cache();

    let (documents_out, configs_out, report) = runner.run(&graph, &documents, &configs, &mut state, &mut cache)?;
    println!("recomputed: {:?}", report.recomputed);
    println!("clean:      {:?}", report.clean);

    for (document_ref, artifact) in &documents_out {
        if documents.get(document_ref) != Some(artifact) {
            bundle.write_document(document_ref, &artifact.0, &artifact.1)?;
        }
    }
    for (config_ref, artifact) in &configs_out {
        if configs.get(config_ref) != Some(artifact) {
            bundle.write_config(config_ref, &artifact.0, &artifact.1)?;
        }
    }
    bundle.save_run_state(&state)?;
    Ok(())
}
